interface.definition:
a!localVariables(
  local!page: "Rotational",
  local!fiscalYearDropdown: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6751857"(),
  local!fiscalYear: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3953700"(),
  {
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_dropdownField_v1"(
            label: "Fiscal Year",
            choiceLabels: local!fiscalYearDropdown,
            choiceValues: local!fiscalYearDropdown,
            saveInto: local!fiscalYear,
            value: local!fiscalYear
          )
        ),
        #"SYSTEM_SYSRULES_columnLayout"(),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: #"SYSTEM_SYSRULES_ButtonArrayLayout"(
            align: "END",
            buttons: {
              #"SYSTEM_SYSRULES_ButtonWidget"(
                size: "LARGE",
                label: "Rotational",
                style: if(
                  local!page = "Rotational",
                  "PRIMARY",
                  "NORMAL"
                ),
                saveInto: a!save(local!page, "Rotational", )
              ),
              #"SYSTEM_SYSRULES_ButtonWidget"(
                size: "LARGE",
                label: "Core",
                style: if(local!page = "Core", "PRIMARY", "NORMAL"),
                saveInto: a!save(local!page, "Core", )
              ),

            }
          )
        )
      }
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      showWhen: local!page = "Rotational",
      contents: #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12820433"(fiscalYear: local!fiscalYear)
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      showWhen: local!page = "Core",
      contents: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6758180"(fiscalYear: local!fiscalYear)
    )
  }
)
